WITH base AS (SELECT *, CONCAT_WS('/', status, method) AS status_method_key, COALESCE(method, 'N/A') AS resolved_method FROM payments WHERE order_id = 29), gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM base), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, MIN(paid_at) AS started_at, COUNT(*) FILTER (WHERE status = 'SUCCESS') AS success_rows, COUNT_IF(status = 'REFUNDED') AS refunded_events, COUNT(DISTINCT status) AS distinct_status, ROUND(AVG(new_group_flag), 2) AS avg_new_group_flag FROM sessionized GROUP BY DATE_TRUNC('MONTH', paid_at) ORDER BY avg_new_group_flag;
